using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollments = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language arts." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events, civilizations, and their impact on the present." }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Title = "Introduction to Programming", Code = "CS 101", Description = "Learn the fundamentals of programming using C#. Topics include variables, control structures, functions, and object-oriented programming basics.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00-9:50 AM", DepartmentId = 1, InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She specializes in programming languages and software design.", IsFeatured = true },
            new() { Id = 2, Title = "Data Structures and Algorithms", Code = "CS 201", Description = "Study of fundamental data structures including arrays, linked lists, trees, and graphs. Algorithm analysis and design techniques.", Credits = 4, Schedule = "Tue/Thu 10:30-11:45 AM", DepartmentId = 1, InstructorName = "Dr. James Morrison", InstructorBio = "Dr. Morrison is an expert in algorithm optimization and has published extensively on graph theory and computational complexity.", IsFeatured = true },
            new() { Id = 3, Title = "Database Systems", Code = "CS 305", Description = "Design and implementation of database systems. Covers relational model, SQL, normalization, and transaction processing.", Credits = 3, Schedule = "Mon/Wed 2:00-3:15 PM", DepartmentId = 1, InstructorName = "Dr. Maria Rodriguez", InstructorBio = "Dr. Rodriguez worked in industry for 10 years at major tech companies before transitioning to academia. Her research focuses on distributed databases.", IsFeatured = false },
            new() { Id = 4, Title = "Calculus I", Code = "MATH 151", Description = "Introduction to differential calculus. Limits, derivatives, and applications of differentiation.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00-10:50 AM", DepartmentId = 2, InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning mathematics educator known for making complex concepts accessible to students.", IsFeatured = true },
            new() { Id = 5, Title = "Linear Algebra", Code = "MATH 220", Description = "Vector spaces, linear transformations, matrices, determinants, and eigenvalues.", Credits = 3, Schedule = "Tue/Thu 1:00-2:15 PM", DepartmentId = 2, InstructorName = "Dr. Emily Watson", InstructorBio = "Dr. Watson specializes in applied mathematics and has contributed to research in machine learning and data science.", IsFeatured = false },
            new() { Id = 6, Title = "Statistics", Code = "MATH 301", Description = "Probability theory, statistical inference, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00-11:50 AM", DepartmentId = 2, InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning mathematics educator known for making complex concepts accessible to students.", IsFeatured = false },
            new() { Id = 7, Title = "General Physics I", Code = "PHYS 101", Description = "Mechanics, thermodynamics, and waves. Includes laboratory component.", Credits = 4, Schedule = "Tue/Thu 9:00-10:15 AM + Lab Fri 2:00-4:50 PM", DepartmentId = 3, InstructorName = "Dr. Alan Foster", InstructorBio = "Dr. Foster is a former NASA researcher with expertise in astrophysics and mechanical systems.", IsFeatured = true },
            new() { Id = 8, Title = "Electromagnetism", Code = "PHYS 202", Description = "Electric fields, magnetic fields, electromagnetic waves, and optics.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00-1:50 PM + Lab Tue 3:00-5:50 PM", DepartmentId = 3, InstructorName = "Dr. Lisa Park", InstructorBio = "Dr. Park's research focuses on quantum electrodynamics and she has mentored numerous graduate students.", IsFeatured = false },
            new() { Id = 9, Title = "Creative Writing", Code = "ENG 205", Description = "Workshop-based course exploring fiction, poetry, and creative nonfiction. Students develop their unique voice.", Credits = 3, Schedule = "Tue/Thu 3:00-4:15 PM", DepartmentId = 4, InstructorName = "Prof. Michael Torres", InstructorBio = "Prof. Torres is a published novelist and poet whose work has appeared in numerous literary journals.", IsFeatured = false },
            new() { Id = 10, Title = "American Literature", Code = "ENG 310", Description = "Survey of American literature from the colonial period to the present. Major authors and literary movements.", Credits = 3, Schedule = "Mon/Wed 10:00-11:15 AM", DepartmentId = 4, InstructorName = "Dr. Patricia Hughes", InstructorBio = "Dr. Hughes is a leading scholar in American literary studies with a focus on 20th-century fiction.", IsFeatured = false },
