```razor
@page "/"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>Home - University Course Catalog</PageTitle>

<div class="text-center mb-5">
    <h1 class="display-4">Welcome to the University Course Catalog</h1>
    <p class="lead text-muted">Explore our departments, browse courses, and enroll today.</p>
    <a href="/courses" class="btn btn-primary btn-lg me-2">Browse Courses</a>
    <a href="/enroll" class="btn btn-outline-primary btn-lg">Enroll Now</a>
</div>

<section class="mb-5">
    <h2 class="mb-3">Featured Courses</h2>
    <div class="row">
        @foreach (var course in featuredCourses)
        {
            <div class="col-md-4 mb-3">
                <div class="card h-100 course-card">
                    <div class="card-body">
                        <h5 class="card-title">@course.Title</h5>
                        <h6 class="card-subtitle mb-2 text-muted">@course.Code · @course.Credits credits</h6>
                        <p class="card-text">@course.Description[..Math.Min(100, course.Description.Length)]...</p>
                    </div>
                    <div class="card-footer bg-transparent">
                        <a href="/courses/@course.Id" class="btn btn-sm btn-outline-primary">View Details</a>
                    </div>
                </div>
            </div>
        }
    </div>
</section>

<section>
    <h2 class="mb-3">Departments</h2>
    <div class="row">
        @foreach (var dept in departments)
        {
            <div class="col-md-4 mb-3">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@dept.Name</h5>
                        <p class="card-text text-muted">@dept.Description</p>
                    </div>
                    <div class="card-footer bg-transparent">
                        <a href="/courses?departmentId=@dept.Id" class="btn btn-sm btn-outline-secondary">View Courses</a>
                    </div>
                </div>
            </div>
        }
    </div>
</section>

@code {
    private List<Course> featuredCourses = new();
    private List<Department> departments = new();

    protected override void OnInitialized()
    {
        featuredCourses = CatalogService.GetFeaturedCourses();
        departments = CatalogService.GetDepartments();
    }
}
```

## 8. Create Courses.razor

Create `/tmp/sv-5548deb46799416ca83040deb9b47889/UniversityCourseCatalog/Components/Pages/Courses.razor`:
```razor
@page "/courses"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>Courses - University Course Catalog</PageTitle>

<h1>Courses</h1>

<form method="get" class="row g-3 mb-4">
    <div class="col-md-6">
        <input type="text" class="form-control" name="search" value="@Search" placeholder="Search courses..." />
    </div>
    <div class="col-md-4">
        <select class="form-select" name="departmentId">
            <option value="">All Departments</option>
            @foreach (var dept in departments)
            {
                <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <button type="submit" class="btn btn-primary w-100">Filter</button>
    </div>
</form>

@if (courses.Any())
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Code</th>
                    <th>Title</th>
                    <th>Credits</th>
                    <th>Schedule</th>
                    <th>Department</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in courses)
                {
                    <tr>
                        <td>@course.Code</td>
                        <td>@course.Title</td>
                        <td>@course.Credits</td>
                        <td>@course.Schedule</td>
                        <td>@(departments.FirstOrDefault(d => d.Id == course.DepartmentId)?.Name)</td>
                        <td><a href="/courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}
else
{
    <div class="alert alert-info">No courses found matching your criteria.</div>
}

