    <div class="col-md-2">
        <button type="submit" class="btn btn-primary w-100">Filter</button>
    </div>
</form>

@if (courses.Any())
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Code</th>
                    <th>Title</th>
                    <th>Credits</th>
                    <th>Schedule</th>
                    <th>Department</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in courses)
                {
                    <tr>
                        <td>@course.Code</td>
                        <td>@course.Title</td>
                        <td>@course.Credits</td>
                        <td>@course.Schedule</td>
                        <td>@(departments.FirstOrDefault(d => d.Id == course.DepartmentId)?.Name)</td>
                        <td><a href="/courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}
else
{
    <div class="alert alert-info">No courses found matching your criteria.</div>
}

@code {
    [SupplyParameterFromQuery]
    public string? Search { get; set; }

    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }

    private List<Course> courses = new();
    private List<Department> departments = new();

    protected override void OnInitialized()
    {
        departments = CatalogService.GetDepartments();
        courses = CatalogService.GetCourses(Search, DepartmentId);
    }
}

@page "/courses/{Id:int}"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

@if (course is not null)
{
    <PageTitle>@course.Title - University Course Catalog</PageTitle>

    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/courses">Courses</a></li>
            <li class="breadcrumb-item active">@course.Code</li>
        </ol>
    </nav>

    <div class="row">
        <div class="col-md-8">
            <h1>@course.Title</h1>
            <span class="badge bg-primary fs-6 mb-3">@course.Code</span>

            <h3 class="mt-4">Description</h3>
            <p>@course.Description</p>

            <h3 class="mt-4">Instructor</h3>
            <h5>@course.InstructorName</h5>
            <p class="text-muted">@course.InstructorBio</p>
        </div>
        <div class="col-md-4">
            <div class="card">
                <div class="card-body">
                    <h5 class="card-title">Course Details</h5>
                    <ul class="list-unstyled">
                        <li class="mb-2"><strong>Credits:</strong> @course.Credits</li>
                        <li class="mb-2"><strong>Schedule:</strong> @course.Schedule</li>
                        <li class="mb-2"><strong>Department:</strong> @(department?.Name)</li>
                    </ul>
                    <a href="/enroll" class="btn btn-primary w-100">Enroll in This Course</a>
                </div>
            </div>
        </div>
    </div>
}
else
{
    <PageTitle>Course Not Found</PageTitle>
    <h1>Course Not Found</h1>
    <p>The requested course could not be found.</p>
    <a href="/courses" class="btn btn-primary">Back to Courses</a>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Course? course;
    private Department? department;

    protected override void OnInitialized()
    {
        course = CatalogService.GetCourse(Id);
        if (course is not null)
        {
            department = CatalogService.GetDepartment(course.DepartmentId);
        }
    }
}

@page "/departments"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>Departments - University Course Catalog</PageTitle>

<h1>Departments</h1>
<p class="lead">Explore our academic departments and their course offerings.</p>

<div class="row">
    @foreach (var dept in departments)
    {
        <div class="col-md-6 mb-4">
            <div class="card h-100">
                <div class="card-body">
                    <h4 class="card-title">@dept.Name</h4>
                    <span class="badge bg-secondary mb-2">@dept.Code</span>
                    <p class="card-text">@dept.Description</p>
                </div>
                <div class="card-footer bg-transparent">
                    <a href="/courses?departmentId=@dept.Id" class="btn btn-outline-primary">View Courses</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private List<Department> departments = new();

    protected override void OnInitialized()
    {
        departments = CatalogService.GetDepartments();
    }
}

@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>Enroll - University Course Catalog</PageTitle>

<h1>Enrollment Request</h1>
<p class="lead">Submit your enrollment request for a course.</p>

@if (submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Enrollment Request Submitted!</h4>
        <p>Thank you, <strong>@Model.StudentName</strong>. Your enrollment request for <strong>@(courses.FirstOrDefault(c => c.Id == Model.CourseId)?.Title)</strong> has been received.</p>
        <hr>
        <p class="mb-0"><a href="/courses">Browse more courses</a> or <a href="/enroll">submit another request</a>.</p>
    </div>
}
else
{
    <div class="row">
        <div class="col-md-8">
            <form method="post">
                <AntiforgeryToken />
                <div class="mb-3">
                    <label for="studentName" class="form-label">Student Name</label>
                    <input type="text" class="form-control" id="studentName" name="Model.StudentName" value="@Model.StudentName" required />
                </div>
                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID</label>
                    <input type="text" class="form-control" id="studentId" name="Model.StudentId" value="@Model.StudentId" required />
                </div>
                <div class="mb-3">
                    <label for="courseId" class="form-label">Course</label>
                    <select class="form-select" id="courseId" name="Model.CourseId" required>
                        <option value="">Select a course...</option>
                        @foreach (var course in courses)
                        {
                            <option value="@course.Id">@course.Code - @course.Title</option>
                        }
                    </select>
                </div>
                <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
            </form>
        </div>
    </div>
}

@code {
    [SupplyParameterFromForm]
    public EnrollmentRequest Model { get; set; } = new();

    private List<Course> courses = new();
    private bool submitted;

    protected override void OnInitialized()
    {
        courses = CatalogService.GetCourses();

        if (HttpMethods.IsPost(HttpContext.Request.Method) && !string.IsNullOrWhiteSpace(Model.StudentName))
        {
            CatalogService.SubmitEnrollmentRequest(Model);
            submitted = true;
        }
    }

    [CascadingParameter]
    public HttpContext HttpContext { get; set; } = default!;
}

